<div class="space-y-5"><?php include __DIR__.'/_nav.php'; ?><div class="flex justify-between"><h1 class="text-xl font-semibold"><?= $edit?'Edit campaign':'New campaign' ?></h1><?php if($edit): ?><a href="/email/campaigns/<?= $campaign['id'] ?>" class="text-sm text-accent-600">Campaign details</a><?php endif ?></div><form method="POST" action="<?= $edit?'/email/campaigns/'.$campaign['id']:'/email/campaigns' ?>" class="space-y-5"><?= csrfField() ?><div class="bg-white border rounded-lg p-5 grid sm:grid-cols-2 gap-4"><label class="text-sm">Internal campaign name *<input required name="name" value="<?= e($campaign['name']??'') ?>" class="mt-1 w-full border rounded px-3 py-2"></label><label class="text-sm">Audience segment<select name="segment_id" class="mt-1 w-full border rounded px-3 py-2"><option value="">Choose segment</option><?php foreach($segments as $s): ?><option value="<?= $s['id'] ?>" <?= (int)($campaign['segment_id']??0)===(int)$s['id']?'selected':'' ?>><?= e($s['name']) ?></option><?php endforeach ?></select><span class="block text-xs text-slate-400 mt-1">Save to refresh the audience preview.</span></label><label class="text-sm">Subject *<input required name="subject" value="<?= e($campaign['subject']??'') ?>" class="mt-1 w-full border rounded px-3 py-2"></label><label class="text-sm">Preheader<input name="preheader" value="<?= e($campaign['preheader']??'') ?>" class="mt-1 w-full border rounded px-3 py-2"></label><label class="text-sm">Template reference<select name="template_id" class="mt-1 w-full border rounded px-3 py-2"><option value="">None</option><?php foreach($templates as $t): ?><option value="<?= $t['id'] ?>" <?= (int)($campaign['template_id']??0)===(int)$t['id']?'selected':'' ?>><?= e($t['name']) ?></option><?php endforeach ?></select><span class="block text-xs text-slate-400 mt-1">Changing this reference does not replace existing content.</span></label><div class="flex gap-4 items-center"><label class="text-sm"><input type="checkbox" name="tracking_opens" <?= !empty($campaign['tracking_opens'])?'checked':'' ?>> Track opens</label><label class="text-sm"><input type="checkbox" name="tracking_clicks" <?= !empty($campaign['tracking_clicks'])?'checked':'' ?>> Track clicks</label></div></div><?php if($audiencePreview!==null): ?><div class="bg-white border rounded-lg p-4"><h2 class="text-sm font-medium">Audience preview</h2><p class="text-2xl font-semibold mt-1"><?= count($audiencePreview['included']) ?> <span class="text-sm font-normal text-slate-500">eligible</span> <span class="text-base text-slate-400 ml-2"><?= count($audiencePreview['excluded']) ?> excluded</span></p><?php if($audiencePreview['excluded']): $reasons=[];foreach($audiencePreview['excluded'] as $x)$reasons[$x['reason']]=($reasons[$x['reason']]??0)+1; ?><div class="flex flex-wrap gap-2 mt-2"><?php foreach($reasons as $reason=>$count): ?><span class="text-xs bg-amber-50 text-amber-800 rounded px-2 py-1"><?= (int)$count ?> <?= e($reason) ?></span><?php endforeach ?></div><?php endif ?></div><?php endif ?><?php include __DIR__.'/_builder.php'; ?><button class="px-4 py-2 bg-accent-600 text-white rounded text-sm">Save campaign</button></form>
<?php if($edit): ?><div class="grid md:grid-cols-2 gap-4"><form method="POST" action="/email/campaigns/<?= $campaign['id'] ?>/test" class="bg-white border rounded-lg p-4 flex gap-2 items-end"><?= csrfField() ?><label class="text-sm flex-1">Send test<input type="email" required name="test_email" class="mt-1 w-full border rounded px-3 py-2" placeholder="you@example.com"></label><button class="px-3 py-2 border rounded text-sm">Send test</button></form><form method="POST" action="/email/campaigns/<?= $campaign['id'] ?>/schedule" class="bg-white border rounded-lg p-4 flex gap-2 items-end" onsubmit="return confirm('Freeze this content and audience, and queue the campaign?')"><?= csrfField() ?><label class="text-sm flex-1">Send time (Europe/London)<input type="datetime-local" name="scheduled_at" class="mt-1 w-full border rounded px-3 py-2"><span class="text-xs text-slate-400">Leave blank to send on the next worker run.</span></label><button class="px-3 py-2 bg-accent-600 text-white rounded text-sm">Schedule</button></form></div><?php endif ?></div>
